css:
.tpl-hf-brand-assemble { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; align-items: center; justify-content: center; background: radial-gradient(65% 65% at 50% 46%, rgba(236,72,153,0.16) 0%, transparent 65%), radial-gradient(50% 50% at 30% 65%, rgba(24,217,232,0.1) 0%, transparent 65%), var(--bg, #080912); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: var(--fg, #ffffff); }
.tpl-hf-brand-assemble .zoom-scale { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; transform-origin: center center; }
.tpl-hf-brand-assemble .zoom-translate { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 0 7%; text-align: center; }
.tpl-hf-brand-assemble .hero-lockup { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: clamp(14px, 2.4vmin, 30px); }
.tpl-hf-brand-assemble .brand-mark { width: clamp(64px, 11vmin, 130px); height: clamp(64px, 11vmin, 130px); border-radius: 26%; background: linear-gradient(135deg, var(--accent, #ec4899), #8b5cf6); display: flex; align-items: center; justify-content: center; box-shadow: 0 18px 48px rgba(236,72,153,0.34), inset 0 1px 0 rgba(255,255,255,0.35); opacity: 0; }
.tpl-hf-brand-assemble .brand-mark svg { width: 54%; height: 54%; }
.tpl-hf-brand-assemble .companion-text { font-size: clamp(24px, 4.2vmin, 52px); font-weight: 500; color: var(--muted, #cbd5e1); letter-spacing: 0.04em; opacity: 0; }
.tpl-hf-brand-assemble .brand-text { font-size: clamp(46px, 8.8vmin, 118px); font-weight: 900; letter-spacing: -0.03em; background: linear-gradient(120deg, #ffffff 25%, var(--accent, #f472b6) 100%); -webkit-background-clip: text; background-clip: text; color: transparent; opacity: 0; }
.tpl-hf-brand-assemble .tagline-pill { margin-top: clamp(20px, 4vh, 44px); padding: 0.55em 1.5em; border-radius: 999px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.14); color: var(--muted, #e2e8f0); font-size: clamp(16px, 2.5vmin, 30px); font-weight: 500; letter-spacing: 0.05em; opacity: 0; }
